        // check if the class is not null
        if (valueClass == null) {
            // throw exception with message "Class of value cannot be null"
            throw new IllegalArgumentException("Class of value cannot be null");
        }

        // check if the class is not assignable from the Map interface
        if (!Map.class.isAssignableFrom(valueClass)) {
            // throw exception with message "Value is not a Map"
            throw new IllegalArgumentException("Value is not a Map");
        }

        // cast the value to a Map
        Map<?, ?> valueMap = (Map<?, ?>) value;

        // process the map
        processMap(valueClass, valueMap);
    } catch (IllegalArgumentException e) {
        // log the exception
        log.error("Exception while registering value: ", e);
    }
}

