    // check if input array is null
    if (array == null) {
        // create new array of size 1 with given component type
        // (note: arrays are 0-indexed)
        return Array.newInstance(newArrayComponentType, 1);
    }

    // compute size of new array (1 greater than input)
    int newSize = array.length + 1;

    // create new array with same component type as input
    Object newArray = Array.newInstance(array.getClass().getComponentType(), newSize);

    // copy elements from input array to new array
    System.arraycopy(array, 0, newArray, 0, array.length);

    // set last element of new array to default value
    newArray[newSize - 1] = null;

    return newArray;
}

