private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Step 1: Check if the node is not null and has a right child
    if (node == null || node.right == null) {
        return null;
    }

    // Step 2: Swap the parent of the node with its right child
    TreeNode<T> rightChild = node.right;
    node.right = rightChild.left;
    rightChild.left = node;

    // Step 3: Update the height of the subtree
    node.height = 1 + Math.max(height(node.left), height(node.right));
    rightChild.height = 1 + Math.max(height(rightChild.left), height(rightChild.right));

    return rightChild;
}

