    if (tour == null || tour.isEmpty()) {
        return null;
    }

    List<E> edges = new ArrayList<>(tour);
    List<V> vertices = new ArrayList<>();

    // Create a new GraphPath
    GraphPath<V,E> path = new GraphPath<>(graph);

    // Add vertices and edges to the path
    for (E edge : edges) {
        V source = edge.getSource();
        V target = edge.getTarget();
        path.addEdge(edge);
        vertices.add(source);
        vertices.add(target);
