        for (int i = 0; i < graph.getNodeCount(); i++) {
            for (int j = 0; j < graph.getNodeCount(); j++) {
                List<Integer> nodePath = new ArrayList<>();
                for (int k = 0; k < graph.getNodeCount(); k++) {
                    if (graph.edgeExist(i, k)) {
