public static Meteor lookup(HttpServletRequest r) {
    // Retrieve the path info from the request
    String path = r.getPathInfo();
    if (path == null) {
        return null;
    }
    // Remove the leading slash from the path if it exists
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    // Split the path into components
    String[] components = path.split("/");
    if (components.length == 0) {
        return null;
    }
    // Look up the meteor based on the first component
    Meteor meteor = Meteors.getMeteor(components[0]);
    if (meteor == null) {
        return null;
    }
    // If there are additional components, try to find a matching meteor
    for (int i = 1; i < components.length; i++) {
        meteor = meteor.getChild(components[i]);
        if (meteor == null) {
            break;
        }
    }
    return meteor;
}

