public void readFrom(final InputStream in) throws IOException {
  // Step 1: Check if the input stream is null
  if (in == null) {
    throw new IllegalArgumentException("Input stream cannot be null");
  }

  // Step 2: Read the entire input stream into a byte array
  byte[] bytes = new byte[in.available()];
  in.read(bytes);

  // Step 3: Reset the read pointer to the start of the byte array
  ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(bytes);
  this.readPointer = 0;

  // Step 4: Fill the buffer with the contents of the byte array
  byte[] buffer = new byte[byteArrayInputStream.available()];
  byteArrayInputStream.read(buffer);
  this.buffer = buffer;

  // Step 5: Close the input stream
  in.close();
}

