public Action inspect(AtmosphereResource atmosphereResource)  {
  AtmosphereResource r = atmosphereResource;
  Action action = Action.CONTINUE;

  // Read the transport value from the AtmosphereResource
  Object transport = r.getRequest().getAttribute(AtmosphereResource.TRANSPORT);

  // If the transport value is equal to Long-Polling, set the suspend flag to true
  if (transport.equals("long-polling")) {
    r.suspend(true);
  } else if (transport.equals("websocket") || transport.equals("sse")) {
    // If the transport value is equal to WebSocket or SSE, set the suspend flag to false
    r.suspend(false);
  } else {
    // If the transport value is invalid, throw an exception
    throw new IllegalArgumentException("Invalid transport value");
  }

  return action;
}

