public static String applyRelativePath(String path, String relativePath) {
    // Handle edge cases where path or relativePath is null or empty
    if (path == null || path.isEmpty() || relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    // Split the path and relativePath into arrays of folders
    String[] pathFolders = path.split("/");
    String[] relativePathFolders = relativePath.split("/");

    // Find the longest common prefix between the two arrays
    int commonPrefixLength = 0;
    for (int i = 0; i < Math.min(pathFolders.length, relativePathFolders.length); i++) {
        if (!pathFolders[i].equals(relativePathFolders[i])) {
            break;
        }
        commonPrefixLength++;
    }

    // Use the common prefix to generate the full file path
    String fullFilePath = "";
    for (int i = commonPrefixLength; i < pathFolders.length; i++) {
        fullFilePath += pathFolders[i] + "/";
    }
    for (int i = commonPrefixLength; i < relativePathFolders.length; i++) {
        fullFilePath += relativePathFolders[i] + "/";
    }

    return fullFilePath;
}

