public static String applyRelativePath(String path, String relativePath) {
    // Step 1: Validate input
    if (path == null || path.isEmpty()) {
        throw new IllegalArgumentException("Path cannot be null or empty");
    }
    if (relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Relative path cannot be null or empty");
    }

    // Step 2: Split the path into segments
    String[] pathSegments = path.split("/");
    String[] relativePathSegments = relativePath.split("/");

    // Step 3: Iterate over the segments and determine the new path
    StringBuilder newPathBuilder = new StringBuilder();
    for (int i = 0; i < relativePathSegments.length; i++) {
        String pathSegment = pathSegments[i];
        String relativePathSegment = relativePathSegments[i];
        if (pathSegment.equals(".")) {
            // Ignore this segment
        } else if (pathSegment.equals("..")) {
            // Go up a directory
            if (i > 0) {
                newPathBuilder.delete(newPathBuilder.length() - pathSegments[i - 1].length() - 1, newPathBuilder.length());
            }
        } else {
            // Append the segment to the new path
            newPathBuilder.append(pathSegment);
            if (i < relativePathSegments.length - 1) {
                newPathBuilder.append("/");
            }
        }
    }

    // Step 4: Return the new path
    return newPathBuilder.toString();
}

