public static String applyRelativePath(String path, String relativePath) {
    // Check if the path is a valid path
    if (!isValidPath(path)) {
        throw new IllegalArgumentException("Invalid path: " + path);
    }

    // Check if the relative path is a valid relative path
    if (!isValidRelativePath(relativePath)) {
        throw new IllegalArgumentException("Invalid relative path: " + relativePath);
    }

    // Split the relative path into its components
    String[] relativeComponents = relativePath.split("/");

    // Create a list to store the final components
    List<String> finalComponents = new ArrayList<>();

    // Go through each component of the relative path
    for (String relativeComponent : relativeComponents) {
        // If the component is "..", remove the last component from the final list
        if (relativeComponent.equals("..")) {
            if (!finalComponents.isEmpty()) {
                finalComponents.remove(finalComponents.size() - 1);
            } else {
                throw new IllegalArgumentException("Invalid relative path: " + relativePath);
            }
        // If the component is ".", skip it
        } else if (relativeComponent.equals(".")) {
            continue;
        } else {
            // Add the component to the final list
            finalComponents.add(relativeComponent);
        }
    }

    // Return the final path
    return String.join("/", finalComponents);
}

