public static String applyRelativePath(String path, String relativePath) {
    // Validate inputs
    if (path == null || path.isEmpty()) {
        throw new IllegalArgumentException("Path cannot be null or empty");
    }
    if (relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Relative path cannot be null or empty");
    }

    // Split the path into segments
    String[] pathSegments = path.split("/");
    String[] relativePathSegments = relativePath.split("/");

    // Resolve the relative path
    int pathSegmentIndex = 0;
    int relativePathSegmentIndex = 0;
    while (pathSegmentIndex < pathSegments.length && relativePathSegmentIndex < relativePathSegments.length) {
        String pathSegment = pathSegments[pathSegmentIndex];
        String relativePathSegment = relativePathSegments[relativePathSegmentIndex];

        if (pathSegment.equals(relativePathSegment)) {
            // Matching path segment found, proceed to next segment
            pathSegmentIndex++;
            relativePathSegmentIndex++;
        } else if (relativePathSegment.equals("..")) {
            // Parent directory segment found, move back to previous segment
            pathSegmentIndex--;
            relativePathSegmentIndex++;
        } else {
            // Unsupported relative path segment found
            throw new IllegalArgumentException("Unsupported relative path segment found: " + relativePathSegment);
        }
    }

    // Return the resolved path with the remaining path segments
    return String.join("/", pathSegments, pathSegmentIndex, pathSegments.length);
}

