public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Invalid row index: " + row);
    }
    if (pane == null || !(pane instanceof JScrollPane)) {
        throw new IllegalArgumentException("JScrollPane pane must be non-null and an instance of JScrollPane");
    }
    if (table.getParent() != pane.getViewport().getView()) {
        throw new IllegalArgumentException("Table must be a direct child of the JScrollPane's viewport");
    }

    // Select the row
    table.setRowSelectionInterval(row, row);

    // Scroll the JScrollPane to the selected row
    Rectangle visibleRect = table.getVisibleRect();
    Rectangle cellRect = table.getCellRect(row, 0, true);
    int scrollBarWidth = 15; // hardcoded for JavaFX
    int scrollBarHeight = 15; // hardcoded for JavaFX
    if (cellRect.x < visibleRect.x) {
        pane.getHorizontalScrollBar().setValue(cellRect.x - scrollBarWidth);
    } else if (cellRect.x + cellRect.width > visibleRect.x + visibleRect.width) {
        pane.getHorizontalScrollBar().setValue(cellRect.x + cellRect.width - visibleRect.x - visibleRect.width + scrollBarWidth);
    }
    if (cellRect.y < visibleRect.y) {
        pane.getVerticalScrollBar().setValue(cellRect.y - scrollBarHeight);
    } else if (cellRect.y + cellRect.height > visibleRect.y + visibleRect.height) {
        pane.getVerticalScrollBar().setValue(cellRect.y + cellRect.height - visibleRect.y - visibleRect.height + scrollBarHeight);
    }
}

