    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;

    if (duration <= FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        long splitSize = FETCH_DATA_DURATION;
        long splitCount = duration / splitSize;
        for (long i = 0; i < splitCount; i++) {
            long currentStart = start + (i * splitSize);
            long currentEnd = start + (i * splitSize) + splitSize;
            timeRanges.add(new TimeRange(currentStart, currentEnd));
        }

        if (duration % splitSize != 0) {
            long finalStart = start + (splitCount * splitSize);
            timeRanges.add(new TimeRange(finalStart, end));
        }
    }

    return timeRanges;
}

