public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid input: file or timeRanges is null or empty");
    }

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.isEmpty()) {
                continue;
            }
            String[] tokens = line.split(",");
            if (tokens.length != 4) {
                throw new IOException("Invalid thread snapshot format");
            }
            String threadName = tokens[0];
            String threadState = tokens[1];
            long startTime = Long.parseLong(tokens[2]);
            long endTime = Long.parseLong(tokens[3]);
            long duration = endTime - startTime;

            if (threadState.equals("RUNNABLE")) {
                threadSnapshots.add(new ThreadSnapshot(threadName, threadState, startTime, endTime, duration));
            }
        }
    }

    return threadSnapshots;
}

